CREATE OR REPLACE FUNCTION public.admin_approve_join_request(p_user_id uuid, p_admin_note text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
    v_admin_id uuid := auth.uid();
    v_request_status text;
begin
    if not private.has_admin_permission('members') then
        raise exception '관리자만 가입을 승인할 수 있습니다.'
            using errcode = '42501';
    end if;

    perform pg_catalog.set_config('app.allow_member_admin_update', 'true', true);

    select jr.status
    into v_request_status
    from public.join_requests as jr
    where jr.user_id = p_user_id
    for update;

    if not found then
        raise exception '가입 신청을 찾을 수 없습니다.'
            using errcode = 'P0002';
    end if;

    if v_request_status not in ('pending', 'held') then
        raise exception '승인 대기 또는 보류 중인 가입 신청만 승인할 수 있습니다.'
            using errcode = '23514';
    end if;

    update public.profiles
    set status = 'approved',
        approved_at = now(),
        approved_by = v_admin_id
    where id = p_user_id;

    update public.join_requests
    set status = 'approved',
        admin_note = nullif(btrim(p_admin_note), ''),
        reviewed_at = now(),
        reviewed_by = v_admin_id
    where user_id = p_user_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.admin_review_join_request(p_user_id uuid, p_decision text, p_admin_note text DEFAULT NULL::text)
